    """
    Simple model that performs a single square matrix multiplication (C = A * B)
    using a custom PTX kernel.
    """
    def __init__(self):
        super().__init__()
    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.shape == B.shape
        assert A.dim() == 2 and A.shape[0] == A.shape[1]
        N = A.shape[0]
        A = A.contiguous()
        B = B.contiguous()
        C = torch.empty((N, N), dtype=A.dtype, device=A.device)
        module = _get_ptx_module()
        # Thread-level tiling: each thread computes 4 output rows (TM=4)
        # within a 32x32 output tile, reducing threads/CTA to 256 while
        # reusing the Bs[k][tx] shared-memory load across the 4 rows.
        block = (32, 8, 1)
        grid = (N // 32, N // 32, 1)
        module.launch(
            "matmul_kernel",
            grid=grid,
            block=block,
            arguments=[A, B, C, u32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

