        # within a 32x32 output tile, reducing threads/CTA to 256 while
        # reusing the Bs[k][tx] shared-memory load across the 4 rows.
        block = (32, 8, 1)
        grid = (N // 32, N // 32, 1)
        module.launch(
            "matmul_kernel",
            grid=grid,
            block=block,
            arguments=[A, B, C, u32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C
